-- Property-level file attachments (Google Drive metadata), keyed by listing.
CREATE TABLE IF NOT EXISTS "panda_realty"."property_list_files" (
  "property_list_file_id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "property_list_id" bigint NOT NULL
    REFERENCES "panda_realty"."panda_properties"("property_list_id")
    ON DELETE CASCADE,
  "file_type" citext,
  "file_link" text,
  "file_name" text,
  "file_size" bigint,
  "google_drive_file_id" text,
  "created_at" timestamp DEFAULT now(),
  "updated_at" timestamp
);

CREATE INDEX IF NOT EXISTS "property_list_files_property_list_id_idx"
  ON "panda_realty"."property_list_files" ("property_list_id");
